756	    /// Signed area of the triangle formed by three nodes.
757	    #[inline]
758	    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
759	        area(
760	            self.nodes[p].x,
761	            self.nodes[p].y,
762	            self.nodes[q].x,
763	            self.nodes[q].y,
764	            self.nodes[r].x,
765	            self.nodes[r].y,
766	        )
767	    }
