#[path = "port/mapbox/mod.rs"] mod pmb;
use pmb::earcut::earcut;

fn ring_area(r:&[[f64;2]])->f64{ // signed, CCW positive
    let mut s=0.0; let n=r.len();
    for i in 0..n { let j=(i+1)%n; s += r[i][0]*r[j][1]-r[j][0]*r[i][1]; }
    s/2.0
}
fn check(name:&str, poly:&Vec<Vec<[f64;2]>>){
    let flat:Vec<[f64;2]> = poly.iter().flat_map(|r|r.iter().cloned()).collect();
    let idx = earcut::<u32,_,_>(poly);
    // expected area = |outer| - sum |holes|
    let mut expect = ring_area(&poly[0]).abs();
    for h in &poly[1..] { expect -= ring_area(h).abs(); }
    let mut sum=0.0; let mut neg=0; let mut pos=0; let mut degen=0; let mut oob=false;
    for t in idx.chunks(3) {
        if t.len()<3 {continue;}
        let (a,b,c)=(t[0] as usize,t[1] as usize,t[2] as usize);
        if a>=flat.len()||b>=flat.len()||c>=flat.len(){oob=true;continue;}
        let ar = ((flat[b][0]-flat[a][0])*(flat[c][1]-flat[a][1])-(flat[c][0]-flat[a][0])*(flat[b][1]-flat[a][1]))/2.0;
        if ar>0.0 {pos+=1} else if ar<0.0 {neg+=1} else {degen+=1}
        sum += ar.abs();
    }
    let ok = !oob && (sum-expect).abs() <= 1e-9*expect.max(1.0) && degen==0 && (pos==0||neg==0);
    println!("{:<38} tris={:<3} area_sum={:<20.12} expect={:<20.12} pos={} neg={} degen={} oob={} => {}",
        name, idx.len()/3, sum, expect, pos, neg, degen, oob, if ok {"VALID"} else {"** SUSPECT **"});
    if !ok { println!("    idx={:?}", idx); }
}
fn circle(cx:f64,cy:f64,r:f64,n:usize,ccw:bool)->Vec<[f64;2]>{
    (0..n).map(|i|{ let mut k=i as f64; if !ccw {k = -(i as f64);} let a=2.0*std::f64::consts::PI*k/(n as f64); [cx+r*a.cos(), cy+r*a.sin()]}).collect()
}
