            printf("n=%-3d all-equal      : %s", n, stable?"order preserved":"REORDERED -> ");
            if(!stable){ for(auto p:q) printf("%d ",p->id); }
            printf("\n");
        }
        // pairs of ties interleaved with distinct keys
        {
            std::vector<Node> store(n);
            std::vector<Node*> q;
            for (int i=0;i<n;i++){ store[i]={(double)(i/2),i}; q.push_back(&store[i]); }
            std::sort(q.begin(), q.end(), [](const Node*a,const Node*b){return a->x < b->x;});
            bool stable=true; for(int i=0;i<n;i++) if(q[i]->id!=i) stable=false;
            printf("n=%-3d tied-pairs     : %s", n, stable?"order preserved":"REORDERED -> ");
            if(!stable){ for(auto p:q) printf("%d ",p->id); }
            printf("\n");
        }
    }
}
